def can_convert_with_scheduled_shifts(s, t, k):
 if len(s)!=len(t):return False
 used=[0]*26
 for left,right in zip(s,t):
  shift=(ord(right)-ord(left))%26
  if shift:
   required=shift+26*used[shift]
   if required>k:return False
   used[shift]+=1
 return True

